+/**
+ * Returns the number of content lines in a code block.
+ *
+ * @param {import("markdownlint").MicromarkToken} codeBlock Code block token.
+ * @returns {number} Number of lines.
+ */
+function getLength(codeBlock) {
+  const { children, endLine, startLine, type } = codeBlock;
+  if (type === "codeIndented") {
+    return endLine - startLine + 1;
+  }
+  const fences = children.filter((child) => child.type === "codeFencedFence");
+  if (fences.length > 1) {
+    return fences[1].startLine - startLine - 1;
+  }
+  const last = children[children.length - 1];
+  const lastLine = (last.type === "lineEnding") ? last.startLine : last.endLine;
+  return lastLine - startLine;
+}
+
+/** @type {import("markdownlint").Rule} */
+export default {
+  "names": [ "MD062", "code-block-max-lines" ],
+  "description": "Code blocks should not exceed the maximum number of lines",
+  "tags": [ "code" ],
+  "parser": "micromark",
+  "function": function MD062(params, onError) {
+    const maximum = Number(params.config.maximum || 0);
+    if (maximum <= 0) {
+      return;
+    }
+    const ignored = Array.isArray(params.config.ignore_languages) ?
+      params.config.ignore_languages.map((language) => String(language).toLowerCase()) :
+      [];
